function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof TERRACOTTA_INFO&&(e.innerHTML=TERRACOTTA_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderHistoryAndMaterials(){if("undefined"==typeof TERRACOTTA_INFO)return;const e=document.getElementById("info-history"),n=document.getElementById("info-materials");e&&(e.innerHTML=`<strong>Historical Background:</strong> ${TERRACOTTA_INFO.historicalBackground}`),n&&(n.innerHTML=`<strong>Raw Materials & Firing Media:</strong> ${TERRACOTTA_INFO.materialsUsed}`)}function renderProcess(){const e=document.getElementById("process-steps");e&&"undefined"!=typeof PROCESS_STEPS&&(e.innerHTML=PROCESS_STEPS.map(e=>`\n        <div class="step-card">\n            <div class="step-num">Step ${e.step}</div>\n            <div class="step-content">\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderStyles(){const e=document.getElementById("styles-grid");e&&"undefined"!=typeof REGIONAL_STYLES&&(e.innerHTML=REGIONAL_STYLES.map(e=>`\n        <div class="style-card">\n            <h3>🏺 ${e.name}</h3>\n            <span class="style-tag">${e.giTag}</span>\n            <p>${e.description}</p>\n            ${e.explorerUrl?`<a href="${e.explorerUrl}" class="explorer-btn" style="text-decoration:none; display:inline-block; margin-top:10px; padding:8px 16px; background:#c2410c; color:#fff; border-radius:6px; font-size:0.88rem; font-weight:700; transition: background 0.2s;">Explore Craft →</a>`:""}\n        </div>\n    `).join(""))}function renderGallery(){const e=document.getElementById("gallery-grid");e&&"undefined"!=typeof GALLERY_IMAGES&&(e.innerHTML=GALLERY_IMAGES.map(e=>`\n        <div class="gallery-card">\n            <img src="${e.url}" alt="${e.caption}" loading="lazy" onerror="this.onerror=null; this.src='../assets/traditional_attires.png';" />\n            <p>${e.caption}</p>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderHistoryAndMaterials(),renderProcess(),renderStyles(),renderGallery(),renderReferences(),initThemeToggle()});